+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import matter from 'gray-matter';
+import { marked } from 'marked';
+
+export interface Frontmatter {
+  title?: string;
+  date?: string | Date;
+  tags?: string[] | string;
+}
+
+export interface Page {
+  title: string;
+  date?: string;
+  tags: string[];
+  html: string;
+  outputPath: string;
+  url: string;
+}
+
+export interface BuildOptions {
+  contentDir?: string;
+  outputDir?: string;
+}
+
+const escapeHtml = (value: string): string =>
+  value.replace(/[&<>'"]/g, (character) => {
+    const entities: Record<string, string> = {
+      '&': '&amp;',
+      '<': '&lt;',
+      '>': '&gt;',
+      "'": '&#39;',
+      '"': '&quot;',
+    };
+    return entities[character];
+  });
+
+const normalizeDate = (value: unknown): string | undefined => {
+  if (value instanceof Date && !Number.isNaN(value.valueOf())) {
+    return value.toISOString().slice(0, 10);
+  }
+  if (typeof value === 'string' && value.trim()) {
+    return value.trim();
+  }
+  return undefined;
+};
+
+const normalizeTags = (value: unknown): string[] => {
+  if (Array.isArray(value)) {
+    return value.filter((tag): tag is string => typeof tag === 'string').map((tag) => tag.trim()).filter(Boolean);
+  }
+  if (typeof value === 'string') {
+    return value.split(',').map((tag) => tag.trim()).filter(Boolean);
+  }
+  return [];
+};
+
+const titleFromFilename = (filename: string): string => {
+  const name = path.basename(filename, path.extname(filename));
+  return name
+    .split(/[-_]+/)
+    .filter(Boolean)
+    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
+    .join(' ');
+};
+
+export function parseMarkdown(source: string, relativePath: string): Page {
+  const parsed = matter(source);
+  const data = parsed.data as Frontmatter;
+  const title = typeof data.title === 'string' && data.title.trim()
+    ? data.title.trim()
+    : titleFromFilename(relativePath);
+  const outputPath = relativePath.replace(/\.md$/i, '.html');
+
+  return {
+    title,
+    date: normalizeDate(data.date),
+    tags: normalizeTags(data.tags),
+    html: marked.parse(parsed.content, { async: false }) as string,
+    outputPath,
+    url: outputPath.split(path.sep).join('/'),
+  };
+}
+
+const renderLayout = (title: string, content: string): string => `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>${escapeHtml(title)}</title>
+</head>
+<body>
+${content}
+</body>
+</html>
+`;
+
+export function renderPage(page: Page): string {
+  const date = page.date ? `\n  <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
+  const tags = page.tags.length
+    ? `\n  <ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
+    : '';
+  return renderLayout(page.title, `  <main>\n  <article>\n  <header>\n  <h1>${escapeHtml(page.title)}</h1>${date}${tags}\n  </header>\n${page.html}  </article>\n  </main>`);
+}
+
+export function renderIndex(pages: Page[]): string {
+  const items = pages.map((page) => {
+    const date = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
+    return `    <li><a href="${escapeHtml(page.url)}">${escapeHtml(page.title)}</a>${date}</li>`;
+  }).join('\n');
+  const list = items ? `\n  <ul>\n${items}\n  </ul>` : '\n  <p>No pages found.</p>';
+  return renderLayout('Pages', `  <main>\n  <h1>Pages</h1>${list}\n  </main>`);
+}
+
+async function markdownFiles(directory: string, base = directory): Promise<string[]> {
+  const entries = await fs.readdir(directory, { withFileTypes: true });
+  const files = await Promise.all(entries.map(async (entry): Promise<string[]> => {
+    const fullPath = path.join(directory, entry.name);
+    if (entry.isDirectory()) return markdownFiles(fullPath, base);
+    return entry.isFile() && /\.md$/i.test(entry.name) ? [path.relative(base, fullPath)] : [];
+  }));
+  return files.flat().sort((left, right) => left.localeCompare(right));
+}
+
+export async function buildSite(options: BuildOptions = {}): Promise<Page[]> {
+  const contentDir = path.resolve(options.contentDir ?? './content');
+  const outputDir = path.resolve(options.outputDir ?? './dist');
+  const outputRelativeToContent = path.relative(contentDir, outputDir);
+  if (outputRelativeToContent === '' || (!outputRelativeToContent.startsWith('..') && !path.isAbsolute(outputRelativeToContent))) {
+    throw new Error('Output directory must not be inside the content directory');
+  }
+
+  const stats = await fs.stat(contentDir).catch(() => undefined);
+  if (!stats?.isDirectory()) {
+    throw new Error(`Content directory does not exist: ${contentDir}`);
+  }
+
+  const files = await markdownFiles(contentDir);
+  const pages = await Promise.all(files.map(async (relativePath) => {
+    const source = await fs.readFile(path.join(contentDir, relativePath), 'utf8');
+    return parseMarkdown(source, relativePath);
+  }));
+
+  pages.sort((left, right) => {
+    if (left.date && right.date && left.date !== right.date) return right.date.localeCompare(left.date);
+    if (left.date !== right.date) return left.date ? -1 : 1;
+    return left.title.localeCompare(right.title);
+  });
+
+  await fs.rm(outputDir, { recursive: true, force: true });
+  await fs.mkdir(outputDir, { recursive: true });
+  await Promise.all(pages.map(async (page) => {
+    const destination = path.join(outputDir, page.outputPath);
+    await fs.mkdir(path.dirname(destination), { recursive: true });
+    await fs.writeFile(destination, renderPage(page), 'utf8');
+  }));
+  await fs.writeFile(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf8');
+  return pages;
+}
*** Add File: src/cli.ts
+#!/usr/bin/env node
+
+import { Command } from 'commander';
+import { buildSite } from './index';
+
+export function createProgram(): Command {
+  const program = new Command();
+  program
+    .name('ssg')
+    .description('Generate a static HTML site from Markdown files')
+    .showHelpAfterError();
+
+  program
+    .command('build')
+    .description('Generate the site')
+    .option('--content <dir>', 'content directory', './content')
+    .option('--output <dir>', 'output directory', './dist')
+    .action(async (options: { content: string; output: string }) => {
+      const pages = await buildSite({ contentDir: options.content, outputDir: options.output });
+      process.stdout.write(`Generated ${pages.length} page${pages.length === 1 ? '' : 's'} in ${pathForMessage(options.output)}\n`);
+    });
+
+  return program;
+}
+
+function pathForMessage(output: string): string {
+  return output.replace(/[\\/]$/, '') || output;
+}
+
+if (require.main === module) {
+  createProgram().parseAsync(process.argv).catch((error: unknown) => {
+    const message = error instanceof Error ? error.message : String(error);
+    process.stderr.write(`Error: ${message}\n`);
+    process.exitCode = 1;
+  });
+}
*** Add File: tests/ssg.test.ts
+import { promises as fs } from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import { buildSite, parseMarkdown, renderPage } from '../src';
+import { createProgram } from '../src/cli';
+
+describe('static site generator', () => {
+  let workspace: string;
+
+  beforeEach(async () => {
+    workspace = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-'));
+  });
+
+  afterEach(async () => {
+    await fs.rm(workspace, { recursive: true, force: true });
+  });
+
+  test('parses Markdown and normalizes frontmatter', () => {
+    const page = parseMarkdown(`---\ntitle: Hello <World>\ndate: 2024-02-03\ntags: one, two\n---\n# Welcome\n\nThis is **bold**.`, 'hello.md');
+
+    expect(page).toMatchObject({
+      title: 'Hello <World>',
+      date: '2024-02-03',
+      tags: ['one', 'two'],
+      outputPath: 'hello.html',
+      url: 'hello.html',
+    });
+    expect(page.html).toContain('<strong>bold</strong>');
+    expect(renderPage(page)).toContain('<title>Hello &lt;World&gt;</title>');
+  });
+
+  test('uses a readable filename when title is absent', () => {
+    expect(parseMarkdown('# Post', 'my-first_post.md').title).toBe('My First Post');
+  });
+
+  test('builds nested pages and a date-sorted index', async () => {
+    const content = path.join(workspace, 'content');
+    const output = path.join(workspace, 'public');
+    await fs.mkdir(path.join(content, 'notes'), { recursive: true });
+    await fs.writeFile(path.join(content, 'older.md'), '---\ntitle: Older\ndate: 2023-01-01\n---\nOld');
+    await fs.writeFile(path.join(content, 'notes', 'new.md'), '---\ntitle: Newer\ndate: 2024-01-01\ntags:\n  - news\n---\nNew');
+    await fs.writeFile(path.join(content, 'ignore.txt'), 'not content');
+
+    const pages = await buildSite({ contentDir: content, outputDir: output });
+    const index = await fs.readFile(path.join(output, 'index.html'), 'utf8');
+    const nested = await fs.readFile(path.join(output, 'notes', 'new.html'), 'utf8');
+
+    expect(pages.map((page) => page.title)).toEqual(['Newer', 'Older']);
+    expect(index).toContain('href="notes/new.html"');
+    expect(index.indexOf('Newer')).toBeLessThan(index.indexOf('Older'));
+    expect(nested).toContain('<li>news</li>');
+    await expect(fs.stat(path.join(output, 'ignore.html'))).rejects.toThrow();
+  });
+
+  test('cleans stale output and supports an empty content directory', async () => {
+    const content = path.join(workspace, 'content');
+    const output = path.join(workspace, 'output');
+    await fs.mkdir(content);
+    await fs.mkdir(output);
+    await fs.writeFile(path.join(output, 'stale.html'), 'stale');
+
+    await expect(buildSite({ contentDir: content, outputDir: output })).resolves.toEqual([]);
+    await expect(fs.stat(path.join(output, 'stale.html'))).rejects.toThrow();
+    await expect(fs.readFile(path.join(output, 'index.html'), 'utf8')).resolves.toContain('No pages found.');
+  });
+
+  test('reports a missing content directory', async () => {
+    await expect(buildSite({
+      contentDir: path.join(workspace, 'missing'),
+      outputDir: path.join(workspace, 'output'),
+    })).rejects.toThrow('Content directory does not exist');
+  });
+
+  test('CLI build honors content and output options', async () => {
+    const content = path.join(workspace, 'articles');
+    const output = path.join(workspace, 'site');
+    await fs.mkdir(content);
+    await fs.writeFile(path.join(content, 'page.md'), '# CLI page');
+    const write = jest.spyOn(process.stdout, 'write').mockImplementation(() => true);
+
+    await createProgram().parseAsync(['node', 'ssg', 'build', '--content', content, '--output', output]);
+
+    await expect(fs.readFile(path.join(output, 'page.html'), 'utf8')).resolves.toContain('<h1>CLI page</h1>');
+    expect(write).toHaveBeenCalledWith(`Generated 1 page in ${output}\n`);
+    write.mockRestore();
+  });
+});
*** Add File: README.md
+# ssg
+
+A TypeScript CLI that turns Markdown files with optional frontmatter into a static HTML site.
+
+```yaml
+---
+title: My post
+date: 2024-01-15
+tags: [news, updates]
+---
+
+# Hello
+```
+
+## Usage
+
+Install dependencies and compile the CLI:
+
+```sh
+npm install
+npm run build
+npx ssg build
+```
+
+Content is read recursively from `./content` and HTML is written to `./dist`. Override either location with:
+
+```sh
+npx ssg build --content ./articles --output ./public
+```
+
+Run tests with `npm test`.
*** End Patch

